from pathlib import Path
import re,json
root=Path('src')
photos=json.load(open('audit/brand/media.json'));byid={p['id']:p for p in photos}
replacements={'/images/placeholder-indoor.jpg':'/video/hero-poster.webp','/images/placeholder-dining.jpg':byid['image-04']['src'],'/images/placeholder-table-texture.jpg':byid['image-15']['src'],'/images/placeholder-skewers.jpg':byid['image-23']['src'],'/images/placeholder-food-bowl.jpg':byid['image-29']['src'],'/images/placeholder-food-light.jpg':byid['image-38']['src'],'/images/placeholder-kitchen-dark.jpg':byid['image-48']['src'],'/images/placeholder-suya.jpg':byid['image-53']['src'],'/images/placeholder-dining-table.jpg':byid['image-39']['src'],'/images/gallery/placeholder-courtyard.svg':byid['image-19']['src']}
for p in root.rglob('*.tsx'):
 s=p.read_text(encoding='utf8')
 for a,b in replacements.items():s=s.replace(a,b)
 s=re.sub(r'alt="Placeholder[^"\n]*"','alt="Dining, food and details at Locale Lagos"',s)
 s=re.sub(r"alt: 'Placeholder[^'\n]*'","alt: 'Dining, food and details at Locale Lagos'",s)
 s=s.replace('Placeholder imagery — photography of the room and tables is still to come.','Around the table at Locale: patterned walls, woven light and shared moments.').replace('Placeholder image — final food photography pending.','Pork ribs, photographed at Locale.').replace('Placeholder photography — credits in public/images/CREDITS.md','Photography & films by Locale')
 s=s.replace('Rattan. Wicker. Woven light. Brick arches.','Rattan. Wicker. Woven light. Graphic walls.').replace('Exposed brick arches frame the room while lush greenery spills towards the courtyard.','Bold patterned columns frame the room while lush greenery fills the courtyard.').replace("label: 'Brick & leaf'","label: 'Pattern & leaf'").replace("words: 'Old brick'","words: 'Bold lines'").replace('Exposed brick arches\n              and lush greenery.','Patterned columns\n              and lush greenery.')
 p.write_text(s,encoding='utf8')
def edit(file,fn):
 p=root/file;p.write_text(fn(p.read_text(encoding='utf8')),encoding='utf8')
edit(Path('components/home/SeatingZones.tsx'),lambda s:s.replace("import { useEffect", "import { Pattern } from '@/components/patterns/Patterns'\nimport { useEffect").replace('            <ArchImage','            {zone.image ? <ArchImage').replace('            />\n            <div','            /> : <div className="arch relative flex aspect-[4/5] items-center justify-center overflow-hidden bg-umber text-paper"><Pattern kind="weave" opacity={.18}/><p className="absolute px-8 text-center font-serif text-4xl">A table of your own.</p></div>}\n            <div'))
edit(Path('components/about/AboutContent.tsx'),lambda s:re.sub(r'      <section className="section-space border-t border-ink/10 bg-cream" aria-labelledby="people-heading">.*?</section>','',s,flags=re.S).replace('              vector\n','').replace('className="mt-14 grid gap-4 sm:mt-16 sm:grid-cols-2"','className="pattern-frame mt-14 grid gap-4 sm:mt-16 sm:grid-cols-[1.4fr_1fr]"'))
edit(Path('components/home/Hero.tsx'),lambda s:s.replace('site.heroVideo.available ?','site.heroVideo.available && !reduced ?').replace('              autoPlay','              autoPlay\n              preload="none"').replace('<source src={site.heroVideo.src}', '<source src="/video/hero.webm" type="video/webm" />\n              <source src={site.heroVideo.src}').replace('bg-ink/45','bg-ink/60').replace('alt="Warm interior with patterned tiles and wooden chairs — placeholder for Locale\'s dining room"','alt="Woven chairs and wooden tables in Locale’s covered dining space"'))
edit(Path('data/site.ts'),lambda s:s.replace("src: '/videos/hero.mp4'","src: '/video/hero.mp4'").replace('available: false, // [EDIT] true after adding a muted H.264 loop to /public/videos','available: true,'))
edit(Path('components/home/GalleryTeaser.tsx'),lambda s:s.replace('const featured = [galleryImages[0], galleryImages[2], galleryImages[6], galleryImages[5]]',"const featured = ['image-04','image-23','image-19','image-49'].map(id => galleryImages.find(image => image.id === id)!)"))
edit(Path('components/gallery/GalleryGrid.tsx'),lambda s:re.sub(r'/\*\* The walkthrough tile.*?\nexport function GalleryGrid', 'export function GalleryGrid',s,flags=re.S).replace('galleryImages, galleryVideo','galleryImages').replace("import { BLUR_DATA_URL }", "import { galleryVideos } from '@/data/videos'\nimport { BLUR_DATA_URL }").replace('blurDataURL={vector ? undefined : BLUR_DATA_URL}','blurDataURL={vector ? undefined : image.blurDataURL ?? BLUR_DATA_URL}').replace('<VideoTile index={visibleImages.length} reduced={reduced} />','''{galleryVideos.filter(video=>activeCategory === 'All' || activeCategory === video.category).map(video=><figure key={video.id} className="mb-6 break-inside-avoid"><video controls muted playsInline preload="none" poster={video.poster} aria-label={video.alt} width={video.width} height={video.height} className="h-auto w-full"><source src={video.webm} type="video/webm"/><source src={video.src} type="video/mp4"/></video><figcaption className="mt-3 text-sm text-umber">{video.alt}</figcaption></figure>)}'''))
edit(Path('components/menu/MenuTabs.tsx'),lambda s:s.replace('  fullMenuLink,\n','').replace("import { contact }", "import Image from 'next/image'\nimport { PatternBand } from '@/components/patterns/Patterns'\nimport { contact }").replace('staggerChildren: 0.06','staggerChildren: 0.015').replace('<h3 className=', '{item.group && <p className="mb-2 text-xs font-semibold">{item.group}</p>}\n        <h3 className=').replace('{item.tags &&', '{item.dietaryNote && <p className="mt-2 text-sm text-leaf">{item.dietaryNote}</p>}\n        {item.tags &&').replace("{typeof item.price === 'number' && (",'{item.price !== null && (').replace('shrink-0 whitespace-nowrap font-serif text-lg','max-w-[40%] shrink-0 text-right font-serif text-lg').replace('{formatNaira(item.price)}',"{typeof item.price === 'number' ? formatNaira(item.price) : item.price}").replace('{active.categories.map((category) => (\n              <section','{active.categories.map((category, categoryIndex) => (\n              <section').replace('                <h2\n','                <PatternBand kind="tile" className="mb-6 max-w-40"/>\n                <h2\n').replace('                <div className="mt-5">','''                {category.note && <p className="mt-4 text-base text-umber">{category.note}</p>}
                {active.id==='food' && categoryIndex % 3 === 2 && <div className="relative mt-8 hidden aspect-[4/1] overflow-hidden lg:block"><Image src={['/images/food/image-25.webp','/images/food/image-41.webp','/images/food/image-49.webp'][Math.floor(categoryIndex/3)]} alt="Dishes photographed at Locale" fill sizes="90vw" className="object-cover"/></div>}
                <div className="mt-5">''').replace('href={fullMenuLink}','href={active.pdf}').replace('            Download full menu (PDF)','            Download full menu (PDF)').replace('{active.intro}</p>','{active.intro}. Prices in naira. Please inform your server of any possible allergies.</p>'))
# Shared source-specific blur data, avoiding neutral generic placeholders where available.
for file in ['components/ui/ArchImage.tsx','components/gallery/Lightbox.tsx','components/home/GalleryTeaser.tsx']:
 edit(Path(file),lambda s:s.replace("import { BLUR_DATA_URL }", "import { media } from '@/data/media'\nimport { BLUR_DATA_URL }").replace('blurDataURL={BLUR_DATA_URL}',"blurDataURL={media.find(photo=>photo.src === "+('src' if 'ArchImage' in file else 'image.src')+")?.blurDataURL ?? BLUR_DATA_URL}"))
# Restrained pattern bands at shared landmarks and offer/reservation surfaces.
for file,needle in [('components/layout/Footer.tsx','      <div className="frame'),('components/home/HappyHourFeature.tsx','        <div className="grid gap-10'),('components/offers/OffersContent.tsx','    <article className="relative overflow-hidden bg-terracotta'),('app/contact/page.tsx','      <section className="section-space bg-cream')]:
 p=root/file;s=p.read_text();s="import { PatternBand } from '@/components/patterns/Patterns'\n"+s if not s.startswith("'use client'") else s.replace("'use client'","'use client'\n\nimport { PatternBand } from '@/components/patterns/Patterns'",1)
 if 'Footer' in file:s=s.replace(needle,'      <PatternBand kind="marks" className="mb-12 text-paper"/>\n'+needle,1)
 elif 'HappyHour' in file:s=s.replace(needle,'        <PatternBand kind="marks" className="mb-8 text-paper"/>\n'+needle,1)
 elif 'Offers' in file:s=s.replace('<article className="relative overflow-hidden bg-terracotta px-6 py-12 text-paper sm:px-10 md:px-14 md:py-16">','<article className="relative overflow-hidden bg-terracotta px-6 py-12 text-paper sm:px-10 md:px-14 md:py-16"><PatternBand kind="marks" className="mb-8 text-paper"/>')
 else:s=s.replace('<div className="frame">','<div className="frame"><PatternBand kind="weave" className="mb-10"/>',1)
 p.write_text(s,encoding='utf8')
edit(Path('components/layout/Preloader.tsx'),lambda s:s.replace("import { Wordmark }", "import { PatternBand } from '@/components/patterns/Patterns'\nimport { Wordmark }").replace('setShow(false), 150','setShow(false), 650').replace('<Wordmark className=','<PatternBand kind="marks" className="mb-6 text-ink"/>\n            <Wordmark className=').replace('className="text-center text-paper"','className="text-center text-ink"'))
# Use the section label as accessible metadata rather than adding repeated eyebrow copy.
edit(Path('components/ui/SectionHeading.tsx'),lambda s:s.replace('<div className={`grid','<div aria-label={label} className={`grid').replace('        <p className="label eyebrow-rule mb-5 text-terracotta">{label}</p>\n',''))
# Map primary UI colors to sampled photographic colors, with light surfaces derived from warm mural ground.
edit(Path('app/globals.css'),lambda s:s.replace('#f3ebe0','#f0e6d7').replace('#faf5ed','#faf6ee').replace('#e3d2bc','#ebd1ae').replace('#c08e70','#b8af9e').replace('#9c4e35','#7f4224').replace('#4c382c','#423327').replace('#241c17','#121111').replace('#52604a','#455232').replace('-0.045em','-0.035em'))
